    "answerText": "**ক এর সমাধান:** বস্তু যে অবস্থায় আছে চিরকাল সে অবস্থায় থাকতে চাওয়ার যে প্রবণতা তাকে জড়তা বলে।\n\n**খ এর সমাধান:** ঘর্ষণের ফলে শক্তির অপচয় ঘটে কিন্তু ঘর্ষণ না থাকলে হাঁটা, চলা বা ব্রেক করা অসম্ভব হতো।\n\n**গ এর সমাধান:** m₁u₁ + m₂u₂ = (m₁ + m₂)v ⇒ 12(10) + 8(5) = 20v ⇒ v = 8 m s⁻¹।\n\n**ঘ এর সমাধান:** পূর্বের গতিশক্তি = 700 J, পরের গতিশক্তি = 640 J। গতিশক্তি সংরক্ষিত না থাকায় সংঘর্ষটি অস্থিতিস্থাপক।",
