    "answerText": "**ক এর সমাধান:** তরল বা গ্যাসীয় মাধ্যমের মধ্য দিয়ে কোনো বস্তু গতিশীল হলে যে ঘর্ষণ বল তৈরি হয় তাকে প্রবাহী ঘর্ষণ বলে।\n\n**খ এর সমাধান:** সবল নিউক্লীয় বল প্রোটন ও নিউট্রনকে একত্রে বেঁধে রাখে, আর দুর্বল নিউক্লীয় বলের কারণে তেজস্ক্রিয় বিটা ক্ষয় ঘটে।\n\n**গ এর সমাধান:** অপচয় ক্ষমতা P_loss = 2000 × 40% = 800 W ⇒ t = 39200 / 800 = 49 s।\n\n**ঘ এর সমাধান:** স্থিতিকোণ θ_s = tan⁻¹(μ) = tan⁻¹(0.25) ≈ 14.04°। আনতি কোণ 15° > 14.04° হওয়ায় বস্তুটি নিচে গড়িয়ে পড়বে।",
