    "questionText": "[কুমিল্লা বোর্ড '২৫] উদ্দীপক: A₁ = 6 cm², A₂ = 30 cm², ছোট পিস্টনে বল F₁ = 250 N, সরণ l₁ = 3 cm। বড় পিস্টনে বস্তু P (ভর = 250 kg)।\n\n**ক.** ক. প্লবতা কাকে বলে? [1 নম্বর]\n**খ.** খ. পর্বতারোহণের জন্য অতিরিক্ত অক্সিজেন সরবরাহের প্রয়োজন হয় কেন? [2 নম্বর]\n**গ.** গ. বড় পিস্টনে কাজের পরিমাণ নির্ণয় করো। [3 নম্বর]\n**ঘ.** ঘ. উদ্দীপক অনুসারে 'P' বস্তুটি সিলিন্ডারের বড় পিস্টনে রাখলে সেটি উপরে ওঠাতে পারবে কি-না? বিশ্লেষণ করো। [4 নম্বর]",
