    "answerText": "**ক এর সমাধান:** তরল বা বায়বীয় পদার্থে আংশিক বা সম্পূর্ণ নিমজ্জিত বস্তুর উপর তরলের ঊর্ধ্বমুখী লব্ধি বলকে প্লবতা বলে।\n\n**খ এর সমাধান:** উচ্চতা বৃদ্ধির সাথে বায়ুমণ্ডলীয় চাপ ও অক্সিজেনের ঘনত্ব হ্রাস পাওয়ায় শ্বাসকষ্ট রোধে অতিরিক্ত অক্সিজেন প্রয়োজন হয়।\n\n**গ এর সমাধান:** কাজের মান W = F₁ l₁ = 250 N × 0.03 m = 7.5 J।\n\n**ঘ এর সমাধান:** F₂ = F₁ × (A₂/A₁) = 250 × (30/6) = 1250 N। P বস্তুর ওজন W = mg = 250 × 9.8 = 2450 N। যেহেতু F₂ < W, তাই পিস্টনটিকে উপরে উঠাতে পারবে না।",
