    "questionText": "[চট্টগ্রাম বোর্ড '২৫] উদ্দীপক: একটি গোলাকার বস্তুর ব্যাসার্ধ 1.5 cm। স্লাইড ক্যালিপার্সের সাহায্যে এর ব্যাস পরিমাপ করে 3.2 cm পাওয়া গেল। বস্তুটিকে ভূমি থেকে 54 m s⁻¹ বেগে খাড়া উপরে নিক্ষেপ করা হলো।\n\n**ক.** ক. ভার্নিয়ার ধ্রুবক কাকে বলে? [1 নম্বর]\n**খ.** খ. সুষম বেগে চলমান বস্তুর গতিপথ শুধুমাত্র সরলরৈখিক— ব্যাখ্যা করো। [2 নম্বর]\n**গ.** গ. গোলাকার বস্তুটির ব্যাস পরিমাপের আপেক্ষিক ত্রুটি নির্ণয় করো। [3 নম্বর]\n**ঘ.** ঘ. ভূমি থেকে 70 m উচ্চতায় বস্তুটিকে ভিন্ন ভিন্ন সময়ে ভিন্ন বেগে দুইবার দেখা যাবে কি-না? গাণিতিকভাবে বিশ্লেষণ করো। [4 নম্বর]",
