    "answerText": "**ক এর সমাধান:** প্রধান স্কেলের ক্ষুদ্রতম এক ভাগের চেয়ে ভার্নিয়ার স্কেলের এক ভাগ যতটুকু ছোট তাকে ভার্নিয়ার ধ্রুবক বলে।\n\n**খ এর সমাধান:** বেগের মান ও দিক উভয়ই অপরিবর্তিত থাকলে কেবল সরলরেখায় গতি সম্ভব।\n\n**গ এর সমাধান:** প্রকৃত ব্যাস d = 2 × 1.5 = 3.0 cm, পরিমাপকৃত ব্যাস = 3.2 cm ⇒ ত্রুটি = 0.2 cm ⇒ আপেক্ষিক ত্রুটি = (0.2/3.0) × 100% = 6.67%।\n\n**ঘ এর সমাধান:** h = ut - 1/2 gt² ⇒ 70 = 54t - 4.9t² ⇒ 4.9t² - 54t + 70 = 0 ⇒ t₁ ≈ 1.52 s এবং t₂ ≈ 9.50 s। বেগ v₁ = 54 - 9.8(1.52) ≈ 39.1 m/s (উর্ধমুখী) এবং v₂ = -39.1 m/s (নিম্নমুখী)। দুইবার ভিন্ন বেগে দেখা যাবে।",
