    "answerText": "**ক এর সমাধান:** কাছাকাছি স্থাপিত দুটি পরিবাহকের মধ্যবর্তী স্থানে অন্তরক রেখে তড়িৎ আধান সঞ্চয় করার যান্ত্রিক ব্যবস্থাকে ধারক বলে।\n\n**খ এর সমাধান:** তড়িৎক্ষেত্র হলো আধানের প্রভাবের স্থানিক অঞ্চল, আর তড়িৎ তীব্রতা হলো ঐ অঞ্চলের কোনো বিন্দুতে একক ধনাত্মক আধানে প্রযুক্ত বলের মান।\n\n**গ এর সমাধান:** F = k q_A q_B / d² ⇒ F = k হতে হলে q_A q_B / d² = 1 ⇒ 1 × q_B / 1² = 1 ⇒ q_B = 1 C হতে হবে।\n\n**ঘ এর সমাধান:** A এর চার্জ হবে +2 C এবং B এর -2 C। ফলে আধানদ্বয়ের মান সমান হওয়ায় প্রতিসম বলরেখা তৈরি হবে।",
