    "questionText": "[সিলেট সরকারি পাইলট উচ্চ বিদ্যালয় '২৫] উদ্দীপক: 10 cm ফোকাস দূরত্বের একটি অবতল দর্পণের মেরু হতে 15 cm সামনে একটি লক্ষ্যবস্তু স্থাপন করা হলো।\n\n**ক.** ক. ফোকাস দূরত্ব কাকে বলে? [1 নম্বর]\n**খ.** খ. সমতল দর্পণে সৃষ্ট প্রতিবিম্বের দুইটি বৈশিষ্ট্য লেখো। [2 নম্বর]\n**গ.** গ. উদ্দীপক অনুযায়ী সৃষ্ট প্রতিবিম্বের বিবর্ধন নির্ণয় করো। [3 নম্বর]\n**ঘ.** ঘ. গঠিত প্রতিবিম্ব রশ্মিচিত্রের সাহায্যে ব্যাখ্যা করো। [4 নম্বর]",
