    "questionText": "[বরিশাল সরকারি বালিকা উচ্চ বিদ্যালয় '২৫] উদ্দীপক: একটি 60% কর্মদক্ষতা সম্পন্ন 2.5 H.P. এর পাম্পকে 800 cm ব্যাস ও 1500 cm উচ্চতাবিশিষ্ট একটি কূপকে পানিশূন্য করার জন্য নেওয়া হলো। কূপে 2/3 অংশ পানি আছে।\n\n**ক.** ক. বায়োফুয়েল কী? [1 নম্বর]\n**খ.** খ. দেখাও যে, কাজ T = 1/2 mv²। [2 নম্বর]\n**গ.** গ. কূপের সম্পূর্ণ পানিশূন্য করতে কত সময় লাগবে? [3 নম্বর]\n**ঘ.** ঘ. কূপের উপরের অর্ধেক পানি শূন্য করতে যে সময় লাগবে, নিচের অর্ধেক পানি শূন্য করতে তার চেয়ে বেশি সময় লাগবে— বিশ্লেষণ করো। [4 নম্বর]",
