    "answerText": "**ক এর সমাধান:** উদ্ভিদ ও প্রাণীর বর্জ্য থেকে উৎপাদিত জৈব জ্বালানিকে বায়োফুয়েল বলে।\n\n**খ এর সমাধান:** কাজ-শক্তি উপপাদ্য অনুযায়ী কৃতকাজ গতিশক্তির পরিবর্তনের সমান।\n\n**গ এর সমাধান:** পানির ভর m = πr²h_w ρ = π(4)²(10)(1000) ≈ 502654.8 kg। গড় উচ্চতা h_bar = 5 + 10/2 = 10 m। W = mgh_bar = 502654.8 × 9.8 × 10 ≈ 4.926 × 10⁷ J। কার্যকর ক্ষমতা P_out = 2.5 × 746 × 60% = 1119 W ⇒ t = W / P_out ≈ 44021 s ≈ 12.23 ঘণ্টা।\n\n**ঘ এর সমাধান:** নিচের অর্ধেকের গড় উচ্চতা উপরের অর্ধেকের চেয়ে বেশি হওয়ায় নিচের অংশের জন্য কৃতকাজ ও প্রয়োজনীয় সময় বেশি হবে।",
